# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, offset=1):
    return [v - offset for v in xs]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(gather(sift(intake(fold(emit(raw))))))

