    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 18.666666666666668, 'max': 36, 'ratio': 0.75})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 41.0, 'max': 81, 'ratio': 1.0})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 26.0, 'max': 49, 'ratio': 0.75})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 74.66666666666667, 'max': 144, 'ratio': 0.75})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 36.333333333333336, 'max': 64, 'ratio': 0.75})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 4.0, 'max': 4, 'ratio': 0.25})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 30.0, 'max': 64, 'ratio': 1.0})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'mean': 63.0, 'max': 121, 'ratio': 0.75})

